package com.nova.godzillagotchi;
import android.app.*;import android.content.*;import android.os.Build;import android.widget.*;import android.graphics.drawable.GradientDrawable;import android.view.View;import android.text.InputFilter;
/** Compact, scrollable native menus; no extra buttons crowd the 720-square habitat. */
public final class CareUI {
 final MainActivity a;CareUI(MainActivity a){this.a=a;}
 interface Choice{void pick(int i);}
 android.graphics.drawable.Drawable icon(final int index){if(index<0)return null;android.graphics.drawable.Drawable result=new android.graphics.drawable.Drawable(){public void draw(android.graphics.Canvas c){android.graphics.Rect b=getBounds();SkinRenderer.Painter painter=new ThemePainter(a.new AndroidPainter(c,a.dashboard.images),a.theme,a.night);if(index==12)RushArt.can(painter,a.theme,b.left+b.width()*.2f,b.top,b.width()*.6f,b.height());else PaperArt.prop(painter,index,b.left,b.top,b.width(),b.height());}public void setAlpha(int value){}public void setColorFilter(android.graphics.ColorFilter filter){}public int getOpacity(){return android.graphics.PixelFormat.TRANSLUCENT;}};int size=(int)(36*a.getResources().getDisplayMetrics().density);result.setBounds(0,0,size,size);return result;}
 int menuIcon(String label){return label.startsWith("KAIJU RUSH")?12:label.startsWith("SALMON")?0:label.startsWith("TUNA")?1:label.startsWith("SARDINES")?2:label.equals("MEDICINE")?10:label.contains("LIGHTS")?8:label.equals("PET HIS HEAD")?7:label.equals("START NEW PET")?3:label.equals("HOW TO CARE")?9:-1;}
 void menu(String title,String[] labels,final Choice action){ScrollView scroll=new ScrollView(a);LinearLayout list=new LinearLayout(a);list.setOrientation(1);int pad=(int)(12*a.getResources().getDisplayMetrics().density);list.setPadding(pad,pad,pad,pad);scroll.addView(list);final AlertDialog dialog=new AlertDialog.Builder(a).setTitle(title).setView(scroll).setNegativeButton("Close",null).create();for(int i=0;i<labels.length;i++){final int n=i;Button b=new Button(a);b.setText(labels[i]);b.setCompoundDrawables(icon(menuIcon(labels[i])),null,null,null);b.setTextSize(15);b.setTextColor(a.theme==Theme.LCD?ThemePainter.LCD_INK:a.INK);GradientDrawable bg=new GradientDrawable();bg.setColor(a.theme==Theme.LCD?ThemePainter.LCD_BG:0xff14566a);bg.setCornerRadius(pad);b.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,(int)(52*a.getResources().getDisplayMetrics().density));lp.bottomMargin=pad;list.addView(b,lp);b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){dialog.dismiss();action.pick(n);}});}dialog.show();}
 void care(){menu("Care for "+a.pet.name,new String[]{"THEME / "+Theme.NAMES[a.theme],"PROFILE & NAME","MEDICINE",a.pet.lightsOff?"TURN LIGHTS ON":"TURN LIGHTS OFF","PET HIS HEAD","FOOD CHOICES","ATTENTION REMINDERS","HOW TO CARE","START NEW PET"},new Choice(){public void pick(int i){if(i==0){themes();return;}switch(i-1){case 0:profile();break;case 1:if(!a.pet.hatched){a.say("Help your egg hatch first.");break;}if(a.pet.medicine()){a.effect="medicine";a.effectEnd=System.currentTimeMillis()+2200;a.say("All better! Food and a bath help too.");}else a.say("No medicine needed. Feeling fine!");break;case 2:a.pet.lightsOff=!a.pet.lightsOff;a.say(a.pet.lightsOff?"Lights out. Sweet monster dreams.":"The habitat lights are on.");break;case 3:a.bond();break;case 4:food();break;case 5:reminders();break;case 7:confirmNewPet();break;default:guide();}a.save();a.refresh();}});}
 void themes(){new AlertDialog.Builder(a).setTitle("Choose a theme").setSingleChoiceItems(Theme.NAMES,a.theme,new DialogInterface.OnClickListener(){public void onClick(DialogInterface dialog,int which){a.changeArtTheme(which);dialog.dismiss();a.say("Theme: "+Theme.NAMES[a.theme]);}}).setNegativeButton("Cancel",null).show();}
 void confirmNewPet(){new AlertDialog.Builder(a).setTitle("Replace "+a.pet.name+" with a new egg?").setMessage("This permanently replaces your current pet and resets its name, XP, growth, care history and game progress. Your theme, reminder and quiet-hour settings stay the same.\n\nThe new pet starts as an egg. This cannot be undone.").setNegativeButton("Keep current pet",null).setPositiveButton("Start new pet",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){a.startNewPet();}}).show();}
 void profile(){final Pet p=a.pet;String date=new java.text.SimpleDateFormat("MMM d, yyyy",java.util.Locale.getDefault()).format(new java.util.Date(p.birthday));new AlertDialog.Builder(a).setTitle(p.name+" / "+p.stage()).setMessage((p.adopted?"Care tracking began: ":"Birthday: ")+date+"\nDays raised"+(p.adopted?" since update":"")+": "+p.ageDays(System.currentTimeMillis())+"\nWeight: "+String.format(java.util.Locale.US,"%.1f",p.weight)+" kaiju kg\nFavorite food: "+p.favoriteFood()+"\nPersonality: "+p.personality()+"\nAppearance: "+p.form()+"\nXP: "+p.xp+(p.level()<4?" / next level "+Pet.LEVEL_XP[p.level()+1]:" / MAX LEVEL")+"\n\nCARE HISTORY\nMeals: "+p.meals+"  Baths: "+p.baths+"\nHead pats: "+p.bonds+"  Games: "+p.games+"\nMedicine: "+p.medicines+"\nComfortable hours: "+(int)p.wellHours+"\nLights-out sleep: "+(int)p.sleepHours+" hours\nCare growth XP: "+(int)(p.wellHours/6)).setPositiveButton("Rename",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){rename();}}).setNegativeButton("Close",null).show();}
 void rename(){final EditText input=new EditText(a);input.setSingleLine(true);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(16)});input.setText(a.pet.name);new AlertDialog.Builder(a).setTitle("Name your kaiju").setView(input).setPositiveButton("Save",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){String name=input.getText().toString().trim();if(!name.isEmpty()){a.pet.name=name;a.say("Hello, "+name+"!");}}}).setNegativeButton("Cancel",null).show();}
 void food(){if(!a.pet.hatched||a.pet.asleep){a.say(!a.pet.hatched?"Tap the egg to hatch first.":"Let him sleep, or tap WAKE first.");return;}menu("Food & drink",new String[]{fishLabel(0),fishLabel(1),fishLabel(2),"KAIJU RUSH / +33% ENERGY"},new Choice(){public void pick(int i){if(i==3){if(a.pet.drinkRush()){a.effect="drink";a.effectEnd=System.currentTimeMillis()+SoundCues.DRINK_MS;a.startCareSound(a.effect,a.effectEnd);a.say("Kaiju Rush! +33% energy (max 100%).");}return;}boolean fresh=a.pet.harborFish(i)>0;a.pet.feed(i);a.fedFish=i;a.pet.lastHappy=System.currentTimeMillis();a.effect="fish";a.effectEnd=System.currentTimeMillis()+SoundCues.FEED_MS;a.startCareSound(a.effect,a.effectEnd);a.say(new String[]{"Salmon","Tuna","Sardines"}[i]+(i==a.pet.favorite?"! My favorite!":"! CHOMP. Happy kaiju.")+(fresh?" Fresh harbor fish!":""));}});}
 String fishLabel(int type){
  String name=Harbor.FISH[type].toUpperCase(java.util.Locale.ROOT);
  int count=a.pet.harborFish(type);
  return count>0?name+" / "+count+" FRESH":name;
 }
 void play(){menu("Choose an adventure",new String[]{"CITY STOMP / 12 ENERGY","MONSTER BATTLE / 12 ENERGY","FISH MATCH / BONDING GAME","WALK TO THE HARBOR"},new Choice(){public void pick(int i){if(i==2){match();return;}if(i==3){a.startHarbor();return;}if(a.pet.sick||a.pet.energy<12){a.say(a.pet.sick?"Medicine and rest before a big adventure.":"Sleep a little to recharge first.");return;}if(i==0)city();else a.chooseOpponent();}});}
 void city(){menu("Choose one building / 12 energy",Landmarks.NAMES,new Choice(){public void pick(int i){a.startRampage(i);}});}
 void match(){if(!a.pet.hatched||a.pet.asleep||a.pet.sick){a.say("Hatch, wake and feel better before playing.");return;}final MatchingGame game=new MatchingGame(System.nanoTime());LinearLayout outer=new LinearLayout(a);outer.setOrientation(1);final TextView status=new TextView(a);status.setText("Find three fish pairs. Tap again after a miss.");status.setPadding(16,10,16,10);outer.addView(status);final Button[] buttons=new Button[6];final String[] names={"SALMON","TUNA","SARDINE"};for(int row=0;row<3;row++){LinearLayout line=new LinearLayout(a);outer.addView(line);for(int col=0;col<2;col++){final int i=row*2+col;Button b=new Button(a);buttons[i]=b;b.setText("?");if(a.theme==Theme.LCD){b.setBackgroundColor(ThemePainter.LCD_BG);b.setTextColor(ThemePainter.LCD_INK);}line.addView(b,new LinearLayout.LayoutParams(0,(int)(52*a.getResources().getDisplayMetrics().density),1));b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){game.tap(i);for(int j=0;j<6;j++){buttons[j].setText(game.visible(j)?names[game.cards[j]]:"?");buttons[j].setCompoundDrawables(game.visible(j)?icon(game.cards[j]):null,null,null,null);buttons[j].setEnabled(!game.matched[j]);}if(game.pairs==3){boolean reward=game.reward(a.pet,System.currentTimeMillis());status.setText(reward?"Matched! +5 XP / +15 JOY":"Matched! Rewards recharge every 10 minutes.");a.save();a.refresh();}else status.setText("Pairs "+game.pairs+"/3 / tap to reveal");}});}}new AlertDialog.Builder(a).setTitle("Fish match").setView(outer).setNegativeButton("Back to pet",null).show();}
 void reminders(){final android.content.SharedPreferences p=a.getSharedPreferences("pet",0);boolean on=p.getBoolean("reminders",false);menu("Attention reminders",new String[]{on?"TURN REMINDERS OFF":"TURN REMINDERS ON","QUIET HOURS: "+p.getInt("quiet_start",21)+":00 - "+p.getInt("quiet_end",8)+":00","ANDROID NOTIFICATION SETTINGS"},new Choice(){public void pick(int i){if(i==0){boolean enabled=!p.getBoolean("reminders",false);p.edit().putBoolean("reminders",enabled).apply();if(enabled){NotificationManager nm=(NotificationManager)a.getSystemService(Context.NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("care","Pet attention calls",NotificationManager.IMPORTANCE_DEFAULT));if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},47);}Attention.schedule(a);a.say(enabled?"Reminders enabled; Android permission is required.":"Reminders are off.");}else if(i==1){quietStart();}else{a.startActivity(new Intent("android.settings.APP_NOTIFICATION_SETTINGS").putExtra("android.provider.extra.APP_PACKAGE",a.getPackageName()));}}});}
 void quietStart(){final android.content.SharedPreferences p=a.getSharedPreferences("pet",0);TimePickerDialog start=new TimePickerDialog(a,new TimePickerDialog.OnTimeSetListener(){public void onTimeSet(TimePicker v,final int hour,int ignored){TimePickerDialog end=new TimePickerDialog(a,new TimePickerDialog.OnTimeSetListener(){public void onTimeSet(TimePicker v,int endHour,int ignored){p.edit().putInt("quiet_start",hour).putInt("quiet_end",endHour).apply();a.say(hour==endHour?"Quiet hours off (matching start and end).":"Quiet hours: "+hour+":00 - "+endHour+":00");}},p.getInt("quiet_end",8),0,true);end.setTitle("Quiet hours END (whole hour)");end.show();}},p.getInt("quiet_start",21),0,true);start.setTitle("Quiet hours START (whole hour)");start.show();}
 void guide(){new AlertDialog.Builder(a).setTitle("Raising your little kaiju").setMessage("New pets hatch after five taps on their egg. Existing pets keep their progress.\n\nFEED: choose a fish; a favorite adds happiness. Kaiju Rush restores 33 energy, capped at 100. CLEAN clears radioactive messes and gives a bath. Messes build up about every three hours. Poor food or hygiene for four hours can cause a tummy ache; CARE > MEDICINE treats it. Your pet never dies.\n\nSLEEP then CARE > LIGHTS OFF gives restful sleep (14 energy/hour versus 8 with lights on). Nighttime brings a bedtime request. Wake him when you are ready to play.\n\nTap Godzilla to pet him: joy and 1 XP, once a minute. PLAY > FISH MATCH awards 5 XP and joy, once every ten minutes. Care needs and long absences are capped at 24 hours per visit.\n\nSix comfortable hours earn 1 care XP. Bonding, good care and lights-out sleep shape personality. Adult pets display a care-influenced crest. Growth thresholds stay 250 / 750 / 1800 / 3600 XP; size and attack damage rise by level.\n\nCARE includes a name, age, weight, favorite food and care history. Existing pets begin age/history tracking with this update.\n\nOptional reminders check roughly hourly, only for needs, at most once every four hours. Default quiet hours are 21:00–08:00. Android may delay delivery; no reminders while playing or sleeping.\n\nCity and monster battles retain Punch / Kick / Tail / Breath. Choose one building for each city outing; destroying it ends the outing. LEAVE CITY ends a smash early. Swipe an edge for Android navigation.\n\nMade by Nova.").setPositiveButton("Got it",null).show();}
}
